// Browser-generated bytes remain private, resumable and bounded on the host.
function transferURL(cache,operation){return '/api/transfer-cache/'+operation+'?'+query({id:cache.id,key:cache.key});}
function transferCreate(path,name,done){request('POST','/api/transfer-cache/create',{path:path,name:name},done);}
function transferWrite(cache,at,bytes,done,attempt){
    var xhr=new XMLHttpRequest(),finished=false;
    function end(error,data){if(finished)return;finished=true;if(error&&(!xhr.status||xhr.status===429||xhr.status>=500)&&(attempt||0)<4){setTimeout(function(){transferWrite(cache,at,bytes,done,(attempt||0)+1);},Math.min(4000,250*Math.pow(2,attempt||0))+Math.random()*150);return;}done(error,data);}
    xhr.open('POST',transferURL(cache,'chunk')+'&offset='+at,true);xhr.setRequestHeader('X-HLS-Token',session.token);xhr.timeout=0;
    xhr.onload=function(){var result;try{result=JSON.parse(xhr.responseText);}catch(ignore){end('暂存响应无法识别');return;}if(xhr.status===200&&result.offset===at+bytes.length)end(null,result);else end(result.error||'暂存块未确认');};xhr.onerror=xhr.ontimeout=function(){end('暂存连接中断');};xhr.send(bytes);return xhr;
}
function transferRead(cache,first,last,total,done){
    var xhr=new XMLHttpRequest();xhr.open('GET',transferURL(cache,'read'),true);xhr.responseType='arraybuffer';xhr.setRequestHeader('Range','bytes='+first+'-'+last);xhr.timeout=0;
    xhr.onload=function(){if(xhr.status!==206||xhr.getResponseHeader('Content-Range')!=='bytes '+first+'-'+last+'/'+total||!xhr.response||xhr.response.byteLength!==last-first+1){done('暂存范围或版本不匹配');return;}done(null,new Uint8Array(xhr.response));};xhr.onerror=xhr.ontimeout=function(){done('读取暂存失败');};xhr.send(null);return xhr;
}
function checkpointPack(value){
    function replacer(key,item){if(key==='handle'||key==='tempHandle')return undefined;if(item instanceof Uint8Array||item instanceof Uint16Array||item instanceof Uint32Array){var raw=new Uint8Array(item.buffer,item.byteOffset,item.byteLength),binary='';for(var i=0;i<raw.length;i++)binary+=String.fromCharCode(raw[i]);return {hlsArray:item instanceof Uint16Array?16:item instanceof Uint32Array?32:8,bytes:btoa(binary)};}return item;}
    var raw=fflate.strToU8(JSON.stringify(value,replacer)),packed=fflate.gzipSync(raw,{level:1}),binary='';for(var i=0;i<packed.length;i++)binary+=String.fromCharCode(packed[i]);return {format:1,bytes:raw.length,data:btoa(binary)};
}
function checkpointUnpack(value){
    if(!value||value.format!==1||!value.bytes||value.bytes>32*1048576)throw new Error('恢复信息大小无效');var binary=atob(value.data),packed=new Uint8Array(binary.length);for(var i=0;i<binary.length;i++)packed[i]=binary.charCodeAt(i);var raw=fflate.gunzipSync(packed,{out:new Uint8Array(value.bytes)});if(raw.length!==value.bytes)throw new Error('恢复信息长度无效');
    return JSON.parse(fflate.strFromU8(raw),function(key,item){if(item&&item.hlsArray){var data=atob(item.bytes),bytes=new Uint8Array(data.length);for(var n=0;n<data.length;n++)bytes[n]=data.charCodeAt(n);return item.hlsArray===16?new Uint16Array(bytes.buffer):item.hlsArray===32?new Uint32Array(bytes.buffer):bytes;}return item;});
}
function transferCheckpoint(t,state,done){
    var cache=state.cache;if(!cache||!cache.serverJournal){done();return;}
    try{var journal={state:checkpointPack(jobSnapshot(state))};if(state.plan&&!t.serverPlanSaved)journal.plan=checkpointPack(state.plan.items);
        if(!t.checkpointQueue)t.checkpointQueue=[];t.checkpointQueue.push({cache:cache,body:{offset:cache.offset||0,journal:journal},done:done});
        function pump(){if(t.checkpointBusy||!t.checkpointQueue.length)return;var item=t.checkpointQueue.shift();t.checkpointBusy=true;request('POST',transferURL(item.cache,'checkpoint'),item.body,function(error){t.checkpointBusy=false;if(!error&&item.body.journal.plan)t.serverPlanSaved=true;item.done(error);pump();});}pump();
    }catch(error){done(error.message||String(error));}
}
function transferCancel(cache,attempt){if(cache)request('POST',transferURL(cache,'cancel'),{},function(error){if(error&&/active/i.test(error)&&(attempt||0)<5)setTimeout(function(){transferCancel(cache,(attempt||0)+1);},500);});}
function transferRestore(t,done){
    if(!t.job||!t.job.cache){done(null);return;}
    request('GET',transferURL(t.job.cache,'status'),null,function(error,result){if(error||!result.journal){done(null);return;}try{var state=checkpointUnpack(result.journal.state);if(state.planRef){if(!result.journal.plan)throw new Error('缺少目录清单');state.plan.items=checkpointUnpack(result.journal.plan);if(state.current&&state.plan.index<state.plan.items.length)state.plan.items[state.plan.index]=state.current;delete state.planRef;delete state.current;}state.cache.offset=result.checkpoint;t.serverPlanSaved=true;t.recovery=state;done(state);}catch(ignore){done(null);}});
}
